.widget {
  position: fixed;
  bottom: 16px;
  right: 16px;
  z-index: 9999;
  font-family: system-ui, sans-serif;
  direction: rtl;
}

.strip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 999px;
  background: #1e293b;
  border: 1px solid #334155;
  color: #e2e8f0;
  cursor: pointer;
